<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import {imageData,type RequestFn} from './media';import {money,date,states} from './lib';
const props=defineProps<{request:RequestFn,order:Record<string,any>}>();const emit=defineEmits<{changed:[],close:[]}>();const methods=ref<Record<string,any>[]>([]),attempt=ref<Record<string,any>|null>(null),selected=ref(''),busy=ref(false),error=ref(''),notice=ref('');const proof=reactive({reference:'',note:'',image_data:''});
async function load(){const d=await props.request(`orders/${props.order.id}/payment`);attempt.value=d.attempt;if(d.attempt){proof.reference=d.attempt.reference||'';proof.note=d.attempt.payer_note||''}else{methods.value=await props.request('payment-methods');selected.value=methods.value[0]?.id||''}}
async function act(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
async function begin(){await act(async()=>{const mobile=matchMedia('(max-width:760px)').matches?'?mobile=1':'';const d=await props.request(`orders/${props.order.id}/payment${mobile}`,'POST',{method_id:selected.value});if(d.url){const u=new URL(d.url);if(u.protocol!=='https:'||!['openapi.alipay.com','openapi-sandbox.dl.alipaydev.com'].includes(u.hostname))throw new Error('支付地址校验失败');location.assign(u.href)}else attempt.value=d.attempt})}
async function file(e:Event){await act(async()=>{const f=(e.target as HTMLInputElement).files?.[0];if(f)proof.image_data=await imageData(f)})}
async function submit(){await act(async()=>{const d=await props.request(`orders/${props.order.id}/receipt`,'POST',{...proof,version:attempt.value?.version});notice.value=d.message;proof.image_data='';await load();emit('changed')})}
onMounted(()=>act(load));
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal" role="dialog" aria-modal="true" aria-label="订单付款"><div class="section-head"><h2>订单付款</h2><button @click="emit('close')" aria-label="关闭">×</button></div><div v-if="error" class="alert error">{{error}}</div><div v-if="notice" class="alert">{{notice}}</div><div class="payment-total"><span>{{order.plan_name||'套餐订单'}}</span><strong>{{money(order.payable)}}</strong><small>付款期限：{{date(order.expires_at)}}</small></div><template v-if="!attempt"><label>收款方式<select v-model="selected"><option v-for="m in methods" :key="m.id" :value="m.id">{{m.name}} · {{m.type==='manual'?'人工核款':'在线核款'}}</option></select></label><p v-if="!methods.length&&!busy" class="empty">管理员尚未启用收款方式，请稍后再试。</p><button class="primary full" @click="begin" :disabled="busy||!selected">确认收款方式</button></template><template v-else><div class="alert" :class="{error:attempt.state==='rejected'||attempt.order_state!=='pending'}"><strong>{{states[attempt.state]||attempt.state}}</strong><p v-if="attempt.review_note">{{attempt.review_note}}</p><small v-if="attempt.state==='submitted'">正在等待实际到账核实，请勿重复付款。最晚核款时间 {{date(attempt.review_deadline)}}</small></div><p>{{attempt.method_name}}</p><p class="pre muted">{{attempt.instructions}}</p><img :src="'/portal/v1/orders/'+order.id+'/payment-code'" class="payment-qr" alt="本订单创建时的收款二维码"><p class="muted">请核对扫码显示的收款人，并支付准确的优惠后金额 {{money(order.payable)}}。</p><form v-if="attempt.order_state==='pending'&&new Date(attempt.expires_at).getTime()>Date.now()&&['awaiting','submitted','rejected'].includes(attempt.state)" @submit.prevent="submit"><label>付款流水号（或上传付款截图）<input v-model="proof.reference" maxlength="100" placeholder="请填写真实交易流水"></label><label>付款说明<textarea v-model="proof.note" maxlength="1000" rows="2"/></label><label>上传付款截图<input type="file" accept="image/png,image/jpeg" @change="file"></label><img v-if="proof.image_data" :src="proof.image_data" class="receipt-preview" alt="待提交付款凭证"><img v-else-if="attempt.proof_available" :src="'/portal/v1/orders/'+order.id+'/receipt?v='+attempt.version" class="receipt-preview" alt="已提交付款凭证"><button class="primary full" :disabled="busy||!proof.reference&&!proof.image_data">{{attempt.state==='submitted'?'补充付款凭证':'我已付款，提交核款'}}</button></form><p v-else-if="attempt.order_state==='pending'&&attempt.state!=='submitted'" class="muted">付款窗口已关闭；如已转账但未提交，请创建工单联系管理员核实。</p></template></section></div></template>
